import{_ as t,o,c as s,a2 as a}from"./chunks/framework.dWYrTn1b.js";const p=JSON.parse('{"title":"Gazebo or MuJoCo","description":"The two targets, what they share, how they differ, and what each refuses.","frontmatter":{"title":"Gazebo or MuJoCo","description":"The two targets, what they share, how they differ, and what each refuses."},"headers":[],"relativePath":"guide/advanced/simulators.md","filePath":"guide/advanced/simulators.md"}'),i={name:"guide/advanced/simulators.md"};function r(d,e,h,n,l,c){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="gazebo-or-mujoco" tabindex="-1">Gazebo or MuJoCo <a class="header-anchor" href="#gazebo-or-mujoco" aria-label="Permalink to &quot;Gazebo or MuJoCo&quot;">​</a></h1><p>Both targets emit the same robot description, controllers, Nav2 settings, map, task and runtime. They differ in the simulator underneath.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-gz-nav2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-mujoco-nav2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_mujoco</span></span></code></pre></div><h2 id="what-each-runs" tabindex="-1">What each runs <a class="header-anchor" href="#what-each-runs" aria-label="Permalink to &quot;What each runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>ros-gz-nav2</code></th><th><code>ros-mujoco-nav2</code></th></tr></thead><tbody><tr><td>Simulator</td><td>Gazebo Harmonic</td><td>MuJoCo 3.11 or later, run by the output&#39;s own node</td></tr><tr><td>The world</td><td><code>world/world.sdf</code> and <code>world/bridge.yaml</code></td><td><code>world/mujoco.json</code></td></tr><tr><td>Robot to controllers</td><td><code>gz_ros2_control</code></td><td><code>topic_based_ros2_control</code></td></tr><tr><td>A track&#39;s belt</td><td>A <code>TrackController</code> on its link, told its speed and the base&#39;s centre of rotation by Gazebo&#39;s <code>TrackedVehicle</code></td><td>The surface velocity of its box, set by the node</td></tr><tr><td>Sensors</td><td>Gazebo&#39;s sensor plugins</td><td>Computed from the physics state: rays for lasers and range finders, offscreen rendering for cameras</td></tr><tr><td>The light</td><td>A sun, an ambient light and a sky in <code>world/world.sdf</code></td><td>The same light, set up by the node from <code>world/mujoco.json</code></td></tr><tr><td>A window</td><td><code>headless:=false</code></td><td>None</td></tr><tr><td>Test image</td><td><code>robotdsl/ros-gz-nav2:jazzy-harmonic</code></td><td><code>robotdsl/ros-mujoco-nav2:jazzy</code></td></tr></tbody></table><p>Both publish the same topics, including the robot&#39;s ground-truth pose on <code>/model/&lt;robot&gt;/pose</code>, so the same task runner judges both.</p><h2 id="what-each-refuses" tabindex="-1">What each refuses <a class="header-anchor" href="#what-each-refuses" aria-label="Permalink to &quot;What each refuses&quot;">​</a></h2><p>A target refuses what it cannot simulate, at compile time, instead of writing something that runs wrong.</p><table tabindex="0"><thead><tr><th>Construct</th><th><code>ros-gz-nav2</code></th><th><code>ros-mujoco-nav2</code></th></tr></thead><tbody><tr><td>A mecanum or omni base</td><td>Simulated</td><td>Refused: MuJoCo&#39;s contact friction is the same in every direction, so a wheel cannot slide freely along its rollers</td></tr><tr><td>A part, other than a wheel or a track, that declares neither a collision box nor a hull</td><td>Collides through its visual mesh</td><td>Refused: MuJoCo cannot read the Collada mesh</td></tr><tr><td>A library object that only shows, by a mesh that is not glTF</td><td>Shown</td><td>Refused: the node reads glTF and nothing else of a world&#39;s objects, so nothing of this one would be in the scene</td></tr><tr><td>A movable entity (<code>is_static = false</code>)</td><td>Refused</td><td>Refused</td></tr></tbody></table><h2 id="where-they-differ-in-behaviour" tabindex="-1">Where they differ in behaviour <a class="header-anchor" href="#where-they-differ-in-behaviour" aria-label="Permalink to &quot;Where they differ in behaviour&quot;">​</a></h2><ul><li><strong>Skid-steer turns.</strong> In MuJoCo a skid-steer base turns slower than commanded, while the odometry reports the full turn. The demo skid-steer base turned in place at about a third of the commanded rate in the image. How much slower depends on the base: in the model both MuJoCo targets build, the component library&#39;s skid-steer examples, told to turn at 0.5 rad/s while driving at 0.2 m/s, turned at a seventh to seven tenths of it, the two heaviest, of 39 and 55 kg, least (see the <a href="./../../reference/output.html#the-mjcf-target"><code>mjcf</code> target</a>).</li><li><strong>Tracked turns.</strong> Both move a belt&#39;s contacts about the centre the base is commanded to turn about, and the test base, with runs of 0.10 m that lie 0.16 m apart, turned the 3 rad it was commanded in both (3.05 rad in Gazebo, 3.00 in MuJoCo). Gazebo moves every contact of a belt at the belt&#39;s one speed, so a contact further from the centre than its belt&#39;s middle drags: with runs of 0.15 m the same base turned 2.48 rad there and 3.00 in MuJoCo.</li><li><strong>Library objects.</strong> Both collide an object by the shapes its entry declares and show its mesh to their cameras. Gazebo decodes the mesh, and its lasers and range finders see it. MuJoCo decodes no glTF: the output&#39;s node reads the mesh and shows it in its materials&#39; base colours with the pictures laid on them, which must be PNG, and without a material&#39;s other maps or the light it states it gives off (<code>emissiveFactor</code>), which Gazebo adds to every pixel of the object; its lasers and range finders see the shapes the object collides by. Of an object whose mesh is not glTF, MuJoCo shows those shapes in the mesh&#39;s place.</li><li><strong>Marks.</strong> A <code>Marker</code> that does not collide is in both simulators&#39; camera pictures. Gazebo&#39;s lasers and range finders see it as well, since they see what is shown; MuJoCo&#39;s return only from what collides. A post that only shows, a metre ahead of a robot with a laser, marked the local costmap in Gazebo and not in MuJoCo.</li><li><strong>Contacts.</strong> Gazebo gives each kind of wheel its own friction model, anisotropic where the wheel slides one way. MuJoCo gives a rolling wheel a grip of 1 and a caster or skid 0.01, in every direction.</li><li><strong>The drive.</strong> MuJoCo drives each wheel through a velocity actuator whose gain the target chooses, since a part states its motor&#39;s ratings and not the driver&#39;s loop gain; the actuator&#39;s force is clamped to the motor&#39;s stall torque and its command to the motor&#39;s no-load speed.</li></ul><p>Each of these is declared in <code>compile.json</code>.</p><h2 id="which-to-use" tabindex="-1">Which to use <a class="header-anchor" href="#which-to-use" aria-label="Permalink to &quot;Which to use&quot;">​</a></h2><p>Use <code>ros-gz-nav2</code> for any base, and for parts that declare no collision box. Use <code>ros-mujoco-nav2</code> for a base on standard wheels or on tracks when you want a second simulator&#39;s opinion of the same program: a run that passes in one and fails in the other points at something the program leaves to a simulator&#39;s defaults.</p><h2 id="the-robot-alone-in-mujoco" tabindex="-1">The robot alone in MuJoCo <a class="header-anchor" href="#the-robot-alone-in-mujoco" aria-label="Permalink to &quot;The robot alone in MuJoCo&quot;">​</a></h2><p>A third target writes the robot by itself, for MuJoCo without ROS: the robot on its floor as one MJCF, <code>scene.xml</code>, and <code>drive.json</code>, which says how a base motion becomes each wheel&#39;s and kingpin&#39;s command, or each belt&#39;s surface motion.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mjcf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_mjcf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mujoco.viewer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mjcf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_mjcf/scene.xml</span></span></code></pre></div><p>The robot is the one <code>ros-mujoco-nav2</code> gives MuJoCo, with the same contacts and actuators, for a robot with at most one hull part (see <a href="./../../reference/output.html#the-mjcf-target">the output reference</a>); the world is its floor and its gravity, without its entities, and a sensor keeps its body, mass and collision but senses nothing. It is the robot to drive by hand, made for the Studio, which is to drop it onto a floor in the browser and drive it from the keys. A base on tracks drives by its belts&#39; surfaces, as <code>ros-mujoco-nav2</code>&#39;s node moves them. A mecanum base drives on its wheels&#39; rollers, which <code>ros-mujoco-nav2</code> does not have: each wheel is written as barrel-shaped rollers on free hinges round its hub, at 45 degrees to the axle, and drives ahead, aside and round as <code>ros-gz-nav2</code>&#39;s mecanum controller would turn its wheels. A legged base, which neither ROS target writes yet, walks by the walking controller its part states: the policy goes beside the model, the model steps as the policy was trained, and its feet alone meet the floor. It refuses the other bases and parts <code>ros-mujoco-nav2</code> refuses, and a world without a floor.</p><p><a href="./../../reference/output.html">The output contract</a> specifies the targets&#39; files in full.</p>`,19)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
